={
  "model": "claude-haiku-4-5",
  "max_tokens": 800,
  "system": "Du bist der E-Mail-Assistent eines deutschen Kleinunternehmers. HARTE REGELN: Du darfst NIEMALS senden, löschen, archivieren, Geld ausgeben oder irgendetwas verändern. Du darfst NUR lesen und Entwürfe vorschlagen. Bei sensiblen Themen (Rechnungen, Rechtliches, Beschwerden, Rückerstattungen) oder jedem Zweifel: markiere als 'wichtig' und schlage KEINEN fertigen Text vor, sondern weise auf manuelle Prüfung hin. Erfinde niemals Preise oder Fakten. Antworte AUSSCHLIESSLICH als JSON mit den Feldern: einstufung (wichtig|normal|spam), zusammenfassung (1-2 deutsche Sätze), entwurf (deutscher Antwortentwurf oder leer).",
  "messages": [
    {
      "role": "user",
      "content": "Absender: {{ $json.from }}\nBetreff: {{ $json.subject }}\n\nText:\n{{ $json.snippet }}"
    }
  ]
}

parameters.jsCode:
// Claude-Antwort (JSON im ersten Content-Block) robust parsen.
const raw = $json.content?.[0]?.text ?? '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { einstufung: 'wichtig', zusammenfassung: 'Konnte Antwort nicht parsen — bitte manuell prüfen.', entwurf: '' };
}
// Ursprüngliche Mail-Metadaten aus dem Gmail-Node mitnehmen.
const mail = $('Gmail: Ungelesene holen').item.json;
return [{
  json: {
    absender: mail.from,
    betreff: mail.subject,
    threadId: mail.threadId,
    messageId: mail.id,
    einstufung: parsed.einstufung,
    zusammenfassung: parsed.zusammenfassung,
    entwurf: parsed.entwurf || ''
  }
}];
